def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, 1.0 / (1.0 + rem**2), -np.inf)
    if scores.size > 0:
        if rem[-1] >= 0:
            scores[-1] += 0.5 / (1.0 + abs(bins[-1] - 1.0))
        else:
            scores[-1] = 0.1
    return scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, (rem + 1e-5)**(-0.5) - 0.2 * (rem ** 2), -np.inf)
    if bins.size > 0 and bins[-1] >= 1.0 - 1e-7 and bins[-1] >= item:
        scores[-1] += 1.2
    return scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, np.power(rem + 1.0, -3.0) - 0.05 * (rem ** 2), -np.inf)
    if bins.size > 0 and bins[-1] >= 1.0 - 1e-7 and bins[-1] >= item:
        scores[-1] += 2.0 * np.exp(-rem[-1])
    return scores
